// Convert original persistent scope snapshots to explicit classical conditions.
// Temporary scopes below enclose ONLY one classical assignment and are balanced.
struct FlatGuards{nb:u64,depth_cap:usize,stack:Vec<u64>,work:u64,assignments:usize}
fn maximum_depth(ops:&[Op])->usize{let(mut depth,mut peak)=(0usize,0usize);for o in ops{match o.kind{K::PushCondition=>{depth+=1;peak=peak.max(depth);},K::PopCondition=>{assert!(depth>0);depth-=1;},_=>{}}}assert_eq!(depth,0);peak}
impl FlatGuards{
 fn new(ops:&[Op])->Self{let nb=quantum_ecc::circuit::analyze_ops(ops.iter()).1;let depth_cap=maximum_depth(ops);Self{nb,depth_cap,stack:vec![],work:nb+depth_cap as u64,assignments:0}}
 fn assign_and(&mut self,out:&mut Vec<Op>,dst:u64,a:Option<u64>,b:Option<u64>){let n=u64::MAX;assert!(a!=Some(dst)&&b!=Some(dst));out.push(make(K::BitStore0,n,n,n,dst,n));match(a,b){(None,None)=>out.push(make(K::BitStore1,n,n,n,dst,n)),(Some(bit),None)|(None,Some(bit))=>out.push(make(K::BitStore1,n,n,n,dst,bit)),(Some(a),Some(b))=>{if a==b{out.push(make(K::BitStore1,n,n,n,dst,a));}else{out.push(make(K::PushCondition,n,n,n,n,a));out.push(make(K::BitStore1,n,n,n,dst,b));out.push(make(K::PopCondition,n,n,n,n,n));}}}self.assignments+=1;}
 fn original(&mut self,o:&Op,out:&mut Vec<Op>)->Option<Op>{let n=u64::MAX;if o.kind==K::PushCondition{assert!(self.stack.len()<self.depth_cap);assert_ne!(o.c_condition.0,n);let dst=self.nb+self.stack.len()as u64;self.assign_and(out,dst,self.stack.last().copied(),Some(o.c_condition.0));self.stack.push(dst);return None;}if o.kind==K::PopCondition{self.stack.pop().expect("balanced source");return None;}if matches!(o.kind,K::Register|K::AppendToRegister|K::DebugPrint){return Some(*o);}let parent=self.stack.last().copied();let per=(o.c_condition.0!=n).then_some(o.c_condition.0);let condition=match(parent,per){(None,None)=>n,(Some(bit),None)|(None,Some(bit))=>bit,(Some(a),Some(b))=>{self.assign_and(out,self.work,Some(a),Some(b));self.work}};let mut flat=*o;flat.c_condition=BitId(condition);flat.validate();Some(flat)}
}
fn flatten(ops:&[Op])->(Vec<Op>,serde_json::Value){let mut f=FlatGuards::new(ops);let mut out=Vec::with_capacity(ops.len()*2);for o in ops{if let Some(flat)=f.original(o,&mut out){out.push(flat);}}assert!(f.stack.is_empty());let(nq,nb,_,_)=quantum_ecc::circuit::analyze_ops(out.iter());let stats=serde_json::json!({"status":"CAPTURED_GUARD_FLATTENING_CONTROL_NOT_A_RESOURCE_IMPROVEMENT","original_operations":ops.len(),"emitted_operations":out.len(),"qubits":nq,"classical_bits":nb,"original_maximum_scope_depth":f.depth_cap,"classical_guard_assignments":f.assignments,"scope":"Original scope values captured at original Push, independent of later writes to source bits. Every original quantum/classical operation has identical effective guard; metadata unchanged. Only balanced one-assignment classical temporary scopes remain. No extra measurement or quantum gate. Precursor for outside-scope reversible peak loans; not a scored candidate."});(out,stats)}

#[cfg(test)]mod flat_guard_tests{
 use super::*;use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;
 struct Words{pattern:u64,at:usize}impl XofReader for Words{fn read(&mut self,b:&mut[u8]){b.copy_from_slice(&self.pattern.rotate_left((self.at%64)as u32).to_le_bytes());self.at+=1;}}
 fn compare(ops:&[Op]){let(out,_)=flatten(ops);let(nq,nb,_,_)=quantum_ecc::circuit::analyze_ops(ops.iter());let(nq2,nb2,_,_)=quantum_ecc::circuit::analyze_ops(out.iter());assert_eq!(nq,nq2);for high in[false,true]{for pattern in[0,u64::MAX,0xa55a_dd33_ff00_1188]{let(mut ra,mut rb)=(Words{pattern,at:0},Words{pattern,at:0});let(mut a,mut b)=(Simulator::new(nq as usize,nb as usize,&mut ra),Simulator::new(nq as usize,nb2 as usize,&mut rb));for lane in 0..64{for q in 0..nq as usize{a.qubits[q]|=((lane>>(q%4)&1)as u64)<<lane;}for bit in 0..nb as usize{a.bits[bit]|=(((lane>>((bit%2)+4)&1!=0)^(high&&bit==2))as u64)<<lane;}}b.qubits.clone_from(&a.qubits);b.bits[..nb as usize].copy_from_slice(&a.bits);a.apply_iter(ops.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits,b.bits[..nb as usize]);assert_eq!(a.phase,b.phase);assert_eq!(a.stats,b.stats);drop((a,b));assert_eq!(ra.at,rb.at);}}}
 #[test]fn nested_captured_guards_survive_original_bit_mutation_and_sibling_reuse(){let n=u64::MAX;compare(&[make(K::PushCondition,n,n,n,n,0),make(K::BitInvert,n,n,n,0,n),make(K::PushCondition,n,n,n,n,1),make(K::CCX,0,1,2,n,0),make(K::BitStore0,n,n,n,1,n),make(K::Z,n,n,2,n,n),make(K::PopCondition,n,n,n,n,n),make(K::PopCondition,n,n,n,n,n),make(K::PushCondition,n,n,n,n,0),make(K::CX,n,0,1,n,1),make(K::PopCondition,n,n,n,n,n)]);}
 #[test]fn measurement_overwriting_its_own_guard_keeps_prewrite_condition_and_rng(){let n=u64::MAX;compare(&[make(K::PushCondition,n,n,n,n,0),make(K::Hmr,n,n,2,1,1),make(K::R,n,n,0,n,1),make(K::Neg,n,n,n,n,1),make(K::PopCondition,n,n,n,n,n)]);}
 #[test]fn every_operation_kind_and_phase_uses_the_same_effective_guard(){let n=u64::MAX;compare(&[make(K::PushCondition,n,n,n,n,0),make(K::X,n,n,0,n,1),make(K::Z,n,n,1,n,1),make(K::CX,n,0,1,n,1),make(K::CZ,n,1,2,n,1),make(K::CCX,0,1,2,n,1),make(K::CCZ,0,1,2,n,1),make(K::Swap,n,1,2,n,1),make(K::BitStore0,n,n,n,2,1),make(K::BitStore1,n,n,n,2,0),make(K::BitInvert,n,n,n,0,1),make(K::Hmr,n,n,2,1,1),make(K::Neg,n,n,n,n,2),make(K::PopCondition,n,n,n,n,n)]);}
 #[test]fn fixed_random_guard_programs_match_every_protected_quantum_classical_phase_and_count(){let n=u64::MAX;let mut seed=0xa8d7135f23649b01u64;for _ in 0..12{let mut ops=vec![];let mut depth=0;for _ in 0..120{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);let cc=if seed&8==0{n}else{seed%3};let t=(seed>>8)%4;let a=(t+1+(seed>>16)%3)%4;let b=(0..4).find(|&q|q!=t&&q!=a).unwrap();ops.push(match seed%11{0 if depth<3=>{depth+=1;make(K::PushCondition,n,n,n,n,seed%3)},1 if depth>0=>{depth-=1;make(K::PopCondition,n,n,n,n,n)},2=>make(K::X,n,n,t,n,cc),3=>make(K::CX,n,a,t,n,cc),4=>make(K::CCX,b,a,t,n,cc),5=>make(K::CCZ,b,a,t,n,cc),6=>make(K::Hmr,n,n,t,seed%3,cc),7=>make(K::R,n,n,t,n,cc),8=>make(K::Swap,n,a,t,n,cc),_=>make(K::BitInvert,n,n,n,seed%3,cc)});}for _ in 0..depth{ops.push(make(K::PopCondition,n,n,n,n,n));}compare(&ops);}}
 #[test]fn failing_to_capture_the_original_push_value_is_detected(){let n=u64::MAX;let ops=[make(K::PushCondition,n,n,n,n,0),make(K::BitInvert,n,n,n,0,n),make(K::X,n,n,0,n,n),make(K::PopCondition,n,n,n,n,n)];let mut ra=Words{pattern:0,at:0};let mut rb=Words{pattern:0,at:0};let mut a=Simulator::new(1,1,&mut ra);let mut b=Simulator::new(1,1,&mut rb);a.bits[0]=0xa55a;b.bits[0]=a.bits[0];a.apply_iter(ops.iter());let bad=[make(K::BitInvert,n,n,n,0,0),make(K::X,n,n,0,n,0)];b.apply_iter(bad.iter());assert_ne!(a.qubits,b.qubits);}
}
